-- 네 방법을 나란히 센다

@Test
@Transactional
void 정리() {
    record Case(String name, Runnable r) {}
    List<Case> cases = List.of(
        new Case("그냥",   () -> memberRepository.findAll()
                .forEach(m -> m.getTeam().getName())),
        new Case("fetch",  () -> memberRepository.findAllWithFetch()
                .forEach(m -> m.getTeam().getName())),
        new Case("graph",  () -> memberRepository.findAllWithGraph()
                .forEach(m -> m.getTeam().getName())),
        new Case("named",  () -> memberRepository.findByAge(10)
                .forEach(m -> m.getTeam().getName())));

    for (Case c : cases) {
        em.clear();
        System.out.printf("%-7s %d개%n", c.name(), counter.count(c.r()));
    }
}

